import { describe, expect, test } from "bun:test";

import { parseStructuredJson } from "../src/agent/json-output";

describe("structured JSON output", () => {
  test("parses raw JSON", () => {
    expect(parseStructuredJson('{"objective":"ship","tasks":[]}')).toEqual({
      objective: "ship",
      tasks: [],
    });
  });

  test("parses JSON inside a Markdown fence", () => {
    expect(parseStructuredJson('```json\n{"objective":"ship"}\n```')).toEqual({
      objective: "ship",
    });
  });

  test("parses a fenced value with prose around it", () => {
    expect(
      parseStructuredJson(
        'Here is the plan:\n```json\n{"tasks":[{"id":"one"}]}\n```\nDone.',
      ),
    ).toEqual({ tasks: [{ id: "one" }] });
  });

  test("keeps braces and brackets inside strings", () => {
    expect(
      parseStructuredJson('{"message":"value with } and ] inside","items":[1,2]}'),
    ).toEqual({ message: "value with } and ] inside", items: [1, 2] });
  });

  test("rejects output without JSON", () => {
    expect(() => parseStructuredJson("not a plan")).toThrow(/valid JSON/);
  });
});
